package com.cinenest.iot.internal;
import org.springframework.stereotype.Repository;import org.springframework.jdbc.core.simple.JdbcClient;
import java.util.*;import java.time.*;
@Repository
class JdbcIotRepository implements IotRepository {
 private final JdbcClient jdbc;JdbcIotRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 org.springframework.jdbc.core.simple.JdbcClient.StatementSpec sql(String text,Object... args){var s=jdbc.sql(text);for(int i=0;i<args.length;i+=2)s.param(args[i].toString(),args[i+1]);return s;}
 public Instant now(){return sql("SELECT clock_timestamp()").query(OffsetDateTime.class).single().toInstant();}
 public Map<String,Object> device(UUID id,UUID venue,boolean lock){return sql("SELECT * FROM cinenest_iot.device WHERE device_id=:d AND venue_id=:v"+(lock?" FOR UPDATE":""),"d",id,"v",venue).query().listOfRows().stream().findFirst().orElseThrow(()->new IotFailure(404));}
 public Map<String,Object> command(UUID id,UUID device){return sql("SELECT * FROM cinenest_iot.command WHERE command_id=:c AND device_id=:d","c",id,"d",device).query().listOfRows().stream().findFirst().orElseThrow(()->new IotFailure(404));}
 public void audit(UUID actor,UUID venue,UUID device,UUID command,String action,String outcome){sql("INSERT INTO cinenest_iot.audit VALUES(:id,:a,:v,:d,:c,:x,:o,clock_timestamp())","id",UUID.randomUUID(),"a",actor,"v",venue,"d",device,"c",command,"x",action,"o",outcome).update();}
 public void rate(UUID actor,int seconds,int count){if(sql("SELECT count(*) FROM cinenest_iot.audit WHERE actor_id=:a AND created_at>clock_timestamp()-make_interval(secs=>:s)","a",actor,"s",seconds).query(Integer.class).single()>=count)throw new IotFailure(429);}
 public void expire(UUID device){for(var c:sql("SELECT * FROM cinenest_iot.command WHERE device_id=:d AND state='PENDING' AND expires_at<=clock_timestamp()","d",device).query().listOfRows()){state((UUID)c.get("command_id"),"EXPIRED");audit(null,(UUID)c.get("venue_id"),device,(UUID)c.get("command_id"),"TTL_EXPIRED","EXPIRED");}}
 public void state(UUID command,String state){sql("UPDATE cinenest_iot.command SET state=:s,revision=revision+1 WHERE command_id=:c","s",state,"c",command).update();}
 public List<Map<String,Object>> commands(UUID device){return sql("SELECT command_id AS id,booking_id,booking_revision,desired,state,revision,correlation_id,starts_at,ends_at,timezone,created_at,expires_at FROM cinenest_iot.command WHERE device_id=:d ORDER BY created_at DESC,command_id DESC LIMIT 50","d",device).query().listOfRows();}
 public List<Map<String,Object>> auditRows(UUID device){return sql("SELECT audit_id AS id,action,outcome,created_at FROM cinenest_iot.audit WHERE device_id=:d ORDER BY created_at DESC,audit_id DESC LIMIT 50","d",device).query().listOfRows();}
 static Instant time(Object x){return x instanceof java.sql.Timestamp t?t.toInstant():((OffsetDateTime)x).toInstant();}
 public List<Map<String,Object>> devices(UUID venue,int page,int size){return sql("SELECT * FROM cinenest_iot.device WHERE venue_id=:v ORDER BY device_id LIMIT :s OFFSET :o","v",venue,"s",size,"o",page*size).query().listOfRows();}
 public Optional<Map<String,Object>> receipt(UUID actor,UUID key){return sql("SELECT * FROM cinenest_iot.receipt WHERE actor_id=:a AND command_key=:k","a",actor,"k",key).query().listOfRows().stream().findFirst();}
 public void receipt(UUID actor,UUID key,String hash,UUID command,String action){sql("INSERT INTO cinenest_iot.receipt(actor_id,command_key,payload_hash,command_id,action) VALUES(:a,:k,:h,:c,:x)","a",actor,"k",key,"h",hash,"c",command,"x",action).update();}
 public void create(UUID command,UUID device,UUID actor,com.cinenest.booking.BookingAccess.Context b,String desired,Instant expiry){sql("INSERT INTO cinenest_iot.command(command_id,device_id,actor_id,venue_id,room_id,booking_id,booking_revision,starts_at,ends_at,timezone,desired,state,correlation_id,expires_at) VALUES(:c,:d,:a,:v,:r,:b,:rev,:start,:end,:tz,:desired,'PENDING',:corr,:expiry)","c",command,"d",device,"a",actor,"v",b.venue(),"r",b.room(),"b",b.booking(),"rev",b.revision(),"start",OffsetDateTime.ofInstant(b.start(),ZoneOffset.UTC),"end",OffsetDateTime.ofInstant(b.end(),ZoneOffset.UTC),"tz",b.timezone(),"desired",desired,"corr",UUID.randomUUID(),"expiry",OffsetDateTime.ofInstant(expiry,ZoneOffset.UTC)).update();sql("UPDATE cinenest_iot.device SET desired=:s,revision=revision+1 WHERE device_id=:d","s",desired,"d",device).update();}
 public int attempts(UUID command){return sql("SELECT count(*) FROM cinenest_iot.attempt WHERE command_id=:c","c",command).query(Integer.class).single();}
 public void evidence(UUID command,UUID device,UUID actor,String action,LightingSimulator.Evidence e){sql("INSERT INTO cinenest_iot.attempt VALUES(:id,:c,:a,:x,:o,:obs,:seq,:at,clock_timestamp())","id",UUID.randomUUID(),"c",command,"a",actor,"x",action,"o",e.outcome(),"obs",e.observation(),"seq",e.sequence(),"at",e.observedAt()==null?null:OffsetDateTime.ofInstant(e.observedAt(),ZoneOffset.UTC)).update();state(command,e.outcome());if(e.observation()!=null)sql("UPDATE cinenest_iot.device SET observed=:o,observation_sequence=:s,observed_at=:t,revision=revision+1 WHERE device_id=:d","o",e.observation(),"s",e.sequence(),"t",OffsetDateTime.ofInstant(e.observedAt(),ZoneOffset.UTC),"d",device).update();}
 public List<UUID> expiryDevices(){return sql("SELECT device_id FROM cinenest_iot.device ORDER BY device_id FOR UPDATE SKIP LOCKED").query(UUID.class).list();}
 public void register(UUID id,UUID venue,UUID room){var old=sql("SELECT * FROM cinenest_iot.device WHERE device_id=:id","id",id).query().listOfRows();if(!old.isEmpty()){if(!venue.equals(old.getFirst().get("venue_id"))||!room.equals(old.getFirst().get("room_id")))throw new IllegalStateException("Synthetic fixture assignment conflict");return;}sql("INSERT INTO cinenest_iot.device(device_id,venue_id,room_id,capability,synthetic,enabled,online) VALUES(:d,:v,:r,'LIGHT_SET_STATE',true,true,true)","d",id,"v",venue,"r",room).update();sql("INSERT INTO cinenest_iot.assignment(assignment_id,device_id,venue_id,room_id) VALUES(:a,:d,:v,:r)","a",UUID.randomUUID(),"d",id,"v",venue,"r",room).update();audit(null,venue,id,null,"SYNTHETIC_BOOTSTRAP","REGISTERED");}
 public void configure(UUID id,UUID venue,boolean enabled,boolean online){var d=device(id,venue,true);if(!Objects.equals(d.get("enabled"),enabled)||!Objects.equals(d.get("online"),online)){sql("UPDATE cinenest_iot.device SET enabled=:e,online=:o,revision=revision+1 WHERE device_id=:d","e",enabled,"o",online,"d",id).update();audit(null,venue,id,null,"SYNTHETIC_FIXTURE_CONFIGURATION","APPLIED");}}
}